func TestRootHelpUsesLibraryLanguage(t *testing.T) {
	out, err := executeHelpForTest("--help")
	if err != nil {
		t.Fatalf("root help: %v", err)
	}
	if !strings.Contains(out, "library   List products in your DriveThruRPG library") {
		t.Fatalf("root help does not advertise library command clearly:\n%s", out)
	}
	if strings.Contains(out, "order-products") {
		t.Fatalf("root help exposes API resource name order-products:\n%s", out)
	}
}

func TestLibraryHelpWrapsDownloadAPI(t *testing.T) {
	out, err := executeHelpForTest("library", "--help")
	if err != nil {
		t.Fatalf("library help: %v", err)
	}
	for _, want := range []string{"prepare-download", "check-download"} {
		if !strings.Contains(out, want) {
			t.Fatalf("library help missing %q:\n%s", want, out)
		}
	}
	if strings.Contains(out, "order-products") {
		t.Fatalf("library help exposes API resource name order-products:\n%s", out)
	}
}

func TestOrderProductsCommandIsNotExposed(t *testing.T) {
	_, err := executeHelpForTest("order-products", "--help")
	if err == nil {
		t.Fatal("order-products command unexpectedly exists")
	}
	if !strings.Contains(err.Error(), "unknown command") {
		t.Fatalf("order-products error = %v, want unknown command", err)
	}
}

